99	const CURSE_SURCHARGE_PERCENT = 50;
100	const HIGH_ENCHANTMENT_LEVEL = 5;
101	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
102	
103	/** The threshold is inclusive: exactly enchantment 5 already counts as high. */
104	function isHighlyEnchanted(item: Item): boolean {
105	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
106	}
107	
108	/**
109	 * The risk the price list reads off a single item. The surcharges stack: an
110	 * item that carries several risks is charged for each of them.
111	 */
112	function itemRiskSurchargePercent(item: Item): number {
113	  const cursePercent = item.cursed === true ? CURSE_SURCHARGE_PERCENT : 0;
114	  const enchantmentPercent = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
115	  return cursePercent + enchantmentPercent;
116	}
117	
118	/**
119	 * The MHPCO reads risk off main items only. A component is a raw ingredient: it
120	 * bears no curse and no enchantment of its own, and inside a block it has no
121	 * premium of its own that a surcharge could be charged against.
122	 */
123	function bearsOwnRisk(item: Item): boolean {
124	  return !isComponent(item.type);
125	}
126	
127	/**
128	 * An item's own risk surcharges are charged on its price-list row, never on the
129	 * policy total.
130	 */
131	function itemRiskSurcharge(item: Item): number {
132	  if (!bearsOwnRisk(item)) {
133	    return 0;
134	  }
135	  return percentOf(mainItemBasePremium(item.type), itemRiskSurchargePercent(item));
136	}
137	
138	function itemSurcharges(items: Item[]): number {
139	  return items.reduce((total, item) => total + itemRiskSurcharge(item), 0);
140	}
141	
142	/** The threshold is inclusive: exactly 2 years already earns the discount. */
143	function isLongStanding(customer: Customer): boolean {
144	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
145	}
146	
147	/**
148	 * The discount is offered on "each contract after their first", so any contract
149	 * preceded by at least one earlier one qualifies -- the very first does not.
150	 */
151	function isFollowUpContract(previousContracts: number): boolean {
152	  return previousContracts > 0;
153	}
154	
155	/**
156	 * Policy-wide modifiers are all charged against the policy base premium, so the
157	 * MHPCO nets them into a single percentage: a long-standing customer earns a
158	 * loyalty discount, a follow-up contract earns its own discount, and every
159	 * quoted policy carries the first-insurance assessment.
160	 *
161	 * The assessment is deliberately unconditional -- it is not a missing check on
162	 * customer history. The MHPCO treats each item in a quote as a first insurance
163	 * regardless of how long the customer has been with the office, so even a
164	 * long-standing customer's follow-up contract still carries the 10 %.
165	 */
166	function policyWideModifierPercent(customer: Customer, previousContracts: number): number {
167	  const loyaltyPercent = isLongStanding(customer) ? -LOYALTY_DISCOUNT_PERCENT : 0;
168	  const followUpPercent = isFollowUpContract(previousContracts) ? -FOLLOW_UP_DISCOUNT_PERCENT : 0;
169	  return FIRST_INSURANCE_SURCHARGE_PERCENT + loyaltyPercent + followUpPercent;
170	}
171	
172	export function quote(customer: Customer, items: Item[], previousContracts: number): number {
173	  // Item-specific modifiers are charged on the affected item's own base premium;
174	  // policy-wide modifiers are charged on the policy base premium, the plain sum
175	  // of all item base premiums -- never on a base that already carries item
176	  // surcharges. Settling then turns the underwritten amount into the sum payable.
177	  const policyBase = policyBasePremium(items);
178	  const netPolicyModifierPercent = policyWideModifierPercent(customer, previousContracts);
179	  const policyModifiers = percentOf(policyBase, netPolicyModifierPercent);
180	  return settlePremium(policyBase + itemSurcharges(items) + policyModifiers);
181	}
